// Returns a four byte integer comprised of the various component parts of the Extended Id field.
// NOTE: Automatically sets the Request/Acknowledge bits to "Request"
uint32_t build_extended_id_uint32(uint8_t iAddress, uint8_t iType, uint8_t iFromAddress, uint16_t iCommand)
{
    uint32_t iCompoundValue;
    iCompoundValue =    ((uint32_t)(iAddress      & 0xFF) << EXTID__TO_ADDRESS_SHIFT)   |
                        ((uint32_t)(iType         & 0x07) << EXTID__TRANSFER_TYPE_SHIFT)         |
                        ((uint32_t)(iFromAddress  & 0xFF) << EXTID__FROM_ADDRESS_SHIFT) |
                        ((uint32_t)(iCommand      & 0x3FF) << EXTID__COMMAND_SHIFT); // Intentionally keep bits 9-8 (the Request-Acknowledge bits. If not set in the comand they default to 0, i.e. "Request": Good)

    // Ensure that the top three bits are 0b001. 
    iCompoundValue &= 0x1FFFFFFF;
    iCompoundValue |= 0x20000000; 

    // Return the result
    return iCompoundValue;
}


